INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4268782, 616722, 67834, '<td valign="top">a nice idea with good composition, but in my opinion the editing has been overdone, especially the sky as it doesn''t seem to fit with the rest of the scene. Good use of slow shutter for the fountain, the crop potentially a little too tight on the left hand side. 5</td>', 'a nice idea with good composition, but in my opinion the editing has been overdone, especially the sky as it doesn''t seem to fit with the rest of the scene. Good use of slow shutter for the fountain, the crop potentially a little too tight on the left hand side. 5', '2007-11-26 00:08:17.000000', NULL, 1),
(4268785, 615936, 67834, '<td valign="top">haha I love the idea! The composition could do with some work and I dislike the way the letters the writing on the bottle look so obviously edited, but the lather on top of the bottle is a nice touch.</td>', 'haha I love the idea! The composition could do with some work and I dislike the way the letters the writing on the bottle look so obviously edited, but the lather on top of the bottle is a nice touch.', '2007-11-26 00:10:26.000000', NULL, 1),
(4268789, 615511, 67834, '<td valign="top">the crop is a little too tight on the right hand side IMO. Nice idea and a well captured shot with lots of detail.</td>', 'the crop is a little too tight on the right hand side IMO. Nice idea and a well captured shot with lots of detail.', '2007-11-26 00:12:03.000000', NULL, 1),
(4268790, 616560, 67834, '<td valign="top">looks like something out of lord of the rings! Love the composition and the light about the tower. The picture does seem a little washed out, maybe the contrast could have done with a tweaking. Other than that a great shot.</td>', 'looks like something out of lord of the rings! Love the composition and the light about the tower. The picture does seem a little washed out, maybe the contrast could have done with a tweaking. Other than that a great shot.', '2007-11-26 00:13:25.000000', NULL, 1),
