(4268800, 615787, 67834, '<td valign="top">love the shot. Has heaps of character and is technically very good. Great composition, lighting and detail and pin sharp.</td>', 'love the shot. Has heaps of character and is technically very good. Great composition, lighting and detail and pin sharp.', '2007-11-26 00:15:48.000000', NULL, 1),
(4268820, 615910, 67834, '<td valign="top">nothing really interesting going on in this scene and not much thought going into the challenge</td>', 'nothing really interesting going on in this scene and not much thought going into the challenge', '2007-11-26 00:23:13.000000', NULL, 1),
(4268833, 616677, 52449, '<td valign="top">The horizon being exactly in the middle of the composition is generally taboo in photography.</td>', 'The horizon being exactly in the middle of the composition is generally taboo in photography.', '2007-11-26 00:28:23.000000', NULL, 1),
(4268837, 614898, 52449, '<td valign="top">IMHO, the headstone that is the subject of this composition is far too small for the DOF used.</td>', 'IMHO, the headstone that is the subject of this composition is far too small for the DOF used.', '2007-11-26 00:30:05.000000', NULL, 1),
(4268839, 615493, 52449, '<td valign="top">I normally enjoy long exposures to make the water silky smooth, but the smoothness of just certain areas of the water doesn''t quite fit in this wide field of vision. If all of the water was blurred, it would be a better photo, IMO. (5)</td>', 'I normally enjoy long exposures to make the water silky smooth, but the smoothness of just certain areas of the water doesn''t quite fit in this wide field of vision. If all of the water was blurred, it would be a better photo, IMO. (5)', '2007-11-26 00:33:09.000000', NULL, 1),
(4268853, 616692, 86331, '<td valign="top">Great concept and thought behind this image. But it seems pretty distorted in the sky. A little noisy too in the upper right hand clouds. But I really like the concept and idea. Good work.</td>', 'Great concept and thought behind this image. But it seems pretty distorted in the sky. A little noisy too in the upper right hand clouds. But I really like the concept and idea. Good work.', '2007-11-26 00:49:13.000000', NULL, 1),
