(4281792, 616596, 74371, '<td valign="top">Nice idea. Just wish was more in focus</td>', 'Nice idea. Just wish was more in focus', '2007-12-02 01:46:59.000000', NULL, 1),
(4281795, 616027, 76430, '<td valign="top">scalvert and the kid from your PB picture?  If not consider it a complement.  If so, we missed you in September and November.</td>', 'scalvert and the kid from your PB picture?  If not consider it a complement.  If so, we missed you in September and November.', '2007-12-02 01:47:33.000000', NULL, 1),
(4281797, 615923, 76430, '<td valign="top">This has to be Iceland.  Excellent Aurora shot and a great job overall in a difficult lighting situation.</td>', 'This has to be Iceland.  Excellent Aurora shot and a great job overall in a difficult lighting situation.', '2007-12-02 01:48:57.000000', NULL, 1),
